import{_ as a,o as e,c as s,a2 as d}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Полнотекстовый поиск","description":"","frontmatter":{},"headers":[],"relativePath":"ru/advanced/search.md","filePath":"ru/advanced/search.md","lastUpdated":1784903584000}'),n={name:"ru/advanced/search.md"};function o(p,t,l,r,c,i){return e(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="полнотекстовыи-поиск" tabindex="-1">Полнотекстовый поиск <a class="header-anchor" href="#полнотекстовыи-поиск" aria-label="Permalink to &quot;Полнотекстовый поиск&quot;">​</a></h1><h2 id="обзор" tabindex="-1">Обзор <a class="header-anchor" href="#обзор" aria-label="Permalink to &quot;Обзор&quot;">​</a></h2><p>swag2mcp включает встроенный движок полнотекстового поиска (bluge), который индексирует все эндпоинты во всех спецификациях. LLM может искать эндпоинты по методу, пути, описанию или тегу — даже не зная ID эндпоинта.</p><h2 id="как-работает-индексация" tabindex="-1">Как работает индексация <a class="header-anchor" href="#как-работает-индексация" aria-label="Permalink to &quot;Как работает индексация&quot;">​</a></h2><p>Когда спецификация добавляется или обновляется, каждый эндпоинт индексируется. Следующие поля доступны для поиска:</p><table tabindex="0"><thead><tr><th>Поле</th><th>Описание</th><th>Пример</th></tr></thead><tbody><tr><td><code>method</code></td><td>HTTP-метод</td><td><code>GET</code>, <code>POST</code>, <code>PUT</code></td></tr><tr><td><code>path</code></td><td>Путь эндпоинта API</td><td><code>/api/v1/users/{id}</code></td></tr><tr><td><code>summary</code></td><td>Краткое описание OpenAPI</td><td>&quot;Найти питомца по ID&quot;</td></tr><tr><td><code>tag</code></td><td>Категория эндпоинта</td><td>&quot;pets&quot;, &quot;users&quot;</td></tr><tr><td><code>_all</code></td><td>Все поля вместе</td><td>method + path + tag + summary</td></tr></tbody></table><p>Индекс перестраивается при каждом запуске MCP-сервера. Он хранится в памяти для быстрого поиска.</p><h2 id="синтаксис-запросов" tabindex="-1">Синтаксис запросов <a class="header-anchor" href="#синтаксис-запросов" aria-label="Permalink to &quot;Синтаксис запросов&quot;">​</a></h2><p>Поиск поддерживает богатый синтаксис запросов для точной фильтрации:</p><table tabindex="0"><thead><tr><th>Пример</th><th>Описание</th></tr></thead><tbody><tr><td><code>pet</code></td><td>Простой текстовый поиск по всем полям</td></tr><tr><td><code>method:GET</code></td><td>Найти все GET-эндпоинты</td></tr><tr><td><code>tag:pets</code></td><td>Найти эндпоинты в теге &quot;pets&quot;</td></tr><tr><td><code>path:&quot;/api/v1/users&quot;</code></td><td>Точное совпадение пути</td></tr><tr><td><code>+method:POST +tag:pet</code></td><td>Должны совпадать оба условия</td></tr><tr><td><code>-method:DELETE</code></td><td>Исключить DELETE-методы</td></tr><tr><td><code>create~</code></td><td>Нечёткий поиск (устойчив к опечаткам)</td></tr><tr><td><code>cr*</code></td><td>Поиск с подстановочным знаком</td></tr><tr><td><code>&quot;find pet&quot;</code></td><td>Поиск фразы</td></tr><tr><td><code>+summary:pet -method:DELETE</code></td><td>Включить &quot;pet&quot; в summary, исключить DELETE</td></tr></tbody></table><h3 id="поиск-по-полям" tabindex="-1">Поиск по полям <a class="header-anchor" href="#поиск-по-полям" aria-label="Permalink to &quot;Поиск по полям&quot;">​</a></h3><p>Вы можете искать в конкретных полях, используя синтаксис <code>field:value</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>method:GET</span></span>
<span class="line"><span>tag:pets</span></span>
<span class="line"><span>path:&quot;/pet/findByStatus&quot;</span></span>
<span class="line"><span>summary:&quot;find pet by status&quot;</span></span></code></pre></div><h3 id="логические-операторы" tabindex="-1">Логические операторы <a class="header-anchor" href="#логические-операторы" aria-label="Permalink to &quot;Логические операторы&quot;">​</a></h3><ul><li><code>+</code> — терм должен совпадать (И)</li><li><code>-</code> — терм не должен совпадать (НЕ)</li><li>Пробел между термами — ИЛИ (любой терм может совпадать)</li></ul><h3 id="нечеткии-поиск-и-подстановочные-знаки" tabindex="-1">Нечёткий поиск и подстановочные знаки <a class="header-anchor" href="#нечеткии-поиск-и-подстановочные-знаки" aria-label="Permalink to &quot;Нечёткий поиск и подстановочные знаки&quot;">​</a></h3><ul><li><code>term~</code> — нечёткий поиск (находит похожие слова, обрабатывает опечатки)</li><li><code>te*</code> — подстановочный знак (соответствует любым символам)</li><li><code>te?t</code> — подстановочный знак для одного символа</li></ul><h2 id="примеры" tabindex="-1">Примеры <a class="header-anchor" href="#примеры" aria-label="Permalink to &quot;Примеры&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Найти все GET-запросы</span></span>
<span class="line"><span>method:GET</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Найти POST-запросы в теге pet</span></span>
<span class="line"><span>+method:POST +tag:pet</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Найти эндпоинты по точному пути</span></span>
<span class="line"><span>path:&quot;/pet/findByStatus&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Найти по описанию</span></span>
<span class="line"><span>&quot;find pet by status&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Найти всё, кроме DELETE</span></span>
<span class="line"><span>+summary:pet -method:DELETE</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Нечёткий поиск &quot;create&quot; (обрабатывает опечатки)</span></span>
<span class="line"><span>create~</span></span></code></pre></div><h2 id="mcp-инструмент" tabindex="-1">MCP-инструмент <a class="header-anchor" href="#mcp-инструмент" aria-label="Permalink to &quot;MCP-инструмент&quot;">​</a></h2><p>MCP-инструмент <code>search</code> предоставляет доступ к поисковому движку для LLM:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>→ search(query: &quot;find pet by status&quot;, limit: 5)</span></span>
<span class="line"><span>← GET /pet/findByStatus — Находит питомцев по статусу</span></span>
<span class="line"><span>   GET /pet/{petId} — Найти питомца по ID</span></span></code></pre></div><h3 id="параметры" tabindex="-1">Параметры <a class="header-anchor" href="#параметры" aria-label="Permalink to &quot;Параметры&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Параметр</th><th>Обязательно</th><th>Описание</th></tr></thead><tbody><tr><td><code>query</code></td><td>Да</td><td>Поисковый запрос (поддерживает структурированный синтаксис)</td></tr><tr><td><code>limit</code></td><td>Да</td><td>Максимальное количество результатов (1-50)</td></tr></tbody></table><h2 id="важные-замечания" tabindex="-1">Важные замечания <a class="header-anchor" href="#важные-замечания" aria-label="Permalink to &quot;Важные замечания&quot;">​</a></h2><ul><li><strong>Индекс в памяти</strong> — перестраивается каждый раз при запуске MCP-сервера. Постоянного файла индекса нет.</li><li><strong>Все поля в нижнем регистре</strong> — поиск нечувствителен к регистру</li><li><strong>Лимит ограничен 50</strong> — вы не можете запросить более 50 результатов</li><li><strong>Неверный синтаксис запроса</strong> возвращает понятное сообщение об ошибке с примерами</li><li><strong>Поле <code>_all</code></strong> объединяет method, path, tag и summary для простого текстового поиска</li></ul>`,26)])])}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
